begin
  select id into strict review_rule_id from public.rules where course_name = 'Мединский курс (Том 1)' and lesson_number = '21' and sort_order = 1;

  delete from public.rule_sections where rule_id = review_rule_id;
  delete from public.rule_sources where rule_id = review_rule_id;

  update public.rules
  set sort_order = 1,
      title = 'مُرَاجَعَةُ الدُّرُوسِ السَّابِقَةِ (повторение предыдущих уроков)',
      rule_ar = 'هَذَا الدَّرْسُ مُرَاجَعَةٌ لِبَعْضِ الدُّرُوسِ السَّابِقَةِ: أَسْمَاءِ الْإِشَارَةِ، وَيَاءِ الْمُتَكَلِّمِ، وَضَمَائِرِ الْمُتَكَلِّمِ وَالْغَائِبِ، وَالنَّعْتِ، وَالْإِضَافَةِ، وَالْمُبْتَدَأِ وَالْخَبَرِ، وَالْمُثَنَّى، وَالْعَدَدِ، وَحُرُوفِ الْجَرِّ.',
      summary = 'هَذَا الدَّرْسُ مُرَاجَعَةٌ لِبَعْضِ الدُّرُوسِ السَّابِقَةِ: أَسْمَاءِ الْإِشَارَةِ، وَيَاءِ الْمُتَكَلِّمِ، وَضَمَائِرِ الْمُتَكَلِّمِ وَالْغَائِبِ، وَالنَّعْتِ، وَالْإِضَافَةِ، وَالْمُبْتَدَأِ وَالْخَبَرِ، وَالْمُثَنَّى، وَالْعَدَدِ، وَحُرُوفِ الْجَرِّ.',
      rule_kind = 'note',
      content = $$<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Назначение урока</span><span class="rule-main-ar" dir="rtl" lang="ar">هَذَا الدَّرْسُ مُرَاجَعَةٌ لِبَعْضِ الدُّرُوسِ السَّابِقَةِ.</span><p class="rule-study-text">Этот урок не вводит новую тему: автор последовательно повторяет пятнадцать ранее изученных положений. Ниже сохранены все пункты и примеры со страниц 33–34.</p></div><div class="rule-study-card"><span class="rule-card-kicker">1–4 · Указательные имена</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا فَصْلُنَا. هَذَا مَكْتَبُ الْمُدَرِّسِ. هَذَا مُحَمَّدٌ. هَذَا مُدَرِّسُنَا.</span><span class="rule-example-ru">1. <span dir="rtl" lang="ar">أَسْمَاءُ الْإِشَارَةِ لِلْقَرِيبِ الْمُذَكَّرِ</span> — указательные имена близкого мужского рода.</span></div><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar" dir="rtl" lang="ar">هَذِهِ مَدْرَسَتِي. هَذِهِ مَكْتَبَةُ الْمَدْرَسَةِ. هَذِهِ مَرْيَمُ. هَذِهِ مُدَرِّسَتُنَا.</span><span class="rule-example-ru">2. <span dir="rtl" lang="ar">أَسْمَاءُ الْإِشَارَةِ لِلْقَرِيبِ الْمُؤَنَّثِ</span> — указательные имена близкого женского рода.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">ذَاكَ كُرْسِيُّهُ. ذَلِكَ مَكْتَبُ الْمُدَرِّسِ. ذَاكَ مُحَمَّدٌ، وَذَلِكَ عَلِيٌّ.</span><span class="rule-example-ru">3. <span dir="rtl" lang="ar">أَسْمَاءُ الْإِشَارَةِ لِلْبَعِيدِ الْمُذَكَّرِ</span> — указательные имена далёкого мужского рода.</span></div><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar" dir="rtl" lang="ar">تِلْكَ مَكَاتِبُ الطُّلَّابِ. تِلْكَ فَاطِمَةُ. تِلْكَ الْكُتُبُ لِلْمُدَرِّسِينَ.</span><span class="rule-example-ru">4. <span dir="rtl" lang="ar">أَسْمَاءُ الْإِشَارَةِ لِلْبَعِيدِ الْمُؤَنَّثِ</span> — указательные имена далёкого женского рода.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">5–9 · Местоимения</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">هَذِهِ مَدْرَسَتِي. تِلْكَ حَقِيبَتِي. هَؤُلَاءِ أَصْدِقَائِي.</span><span class="rule-example-ru">5. <span dir="rtl" lang="ar">يَاءُ الْمُتَكَلِّمِ</span> — йа говорящего: «мой / моя / мои».</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا فَصْلُنَا. فِي فَصْلِنَا عَشَرَةُ طُلَّابٍ. هَذَا مُدَرِّسُنَا. نَحْنُ نُحِبُّهُ.</span><span class="rule-example-ru">6. <span dir="rtl" lang="ar">ضَمِيرُ الْجَمْعِ لِلْمُتَكَلِّمِ</span> — местоимение множественного числа говорящих.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">هُوَ فَصْلٌ وَاسِعٌ. فِيهِ نَافِذَتَانِ. فِيهِ مَكَاتِبُ. فِيهِ سَبُّورَةٌ. هُوَ مِنَ الْيَابَانِ.</span><span class="rule-example-ru">7. <span dir="rtl" lang="ar">ضَمِيرُ الْغَائِبِ لِلْمُفْرَدِ الْمُذَكَّرِ</span> — «он» и связанные с ним формы.</span></div><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar" dir="rtl" lang="ar">هِيَ قَرِيبَةٌ. هِيَ مَدْرَسَةٌ كَبِيرَةٌ. لَهَا ثَلَاثَةُ أَبْوَابٍ. أَبْوَابُهَا مَفْتُوحَةٌ.</span><span class="rule-example-ru">8. <span dir="rtl" lang="ar">ضَمِيرُ الْغَائِبِ لِلْمُفْرَدِ الْمُؤَنَّثِ</span> — «она» и связанные с ней формы.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">كَرَاسِيُّهُمْ. هُمْ مِنْ بِلَادٍ مُخْتَلِفَةٍ. لُغَاتُهُمْ مُخْتَلِفَةٌ. أَلْوَانُهُمْ مُخْتَلِفَةٌ. دِينُهُمْ وَاحِدٌ.</span><span class="rule-example-ru">9. <span dir="rtl" lang="ar">ضَمِيرُ الْغَائِبِ لِلْجَمْعِ الْمُذَكَّرِ</span> — «они» и суффикс «их» для мужской группы.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">10–15 · Связи и формы</span><div class="rule-example-list"><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar" dir="rtl" lang="ar">مَدْرَسَةٌ كَبِيرَةٌ. فُصُولٌ كَبِيرَةٌ. فَصْلٌ وَاسِعٌ. نَافِذَتَانِ كَبِيرَتَانِ. هُمْ مِنْ بِلَادٍ مُخْتَلِفَةٍ. رَجُلٌ صَالِحٌ.</span><span class="rule-example-ru">10. <span dir="rtl" lang="ar">مَنْعُوتٌ وَنَعْتٌ</span> — определяемое слово и согласованное определение.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ثَلَاثَةُ أَبْوَابٍ. مَكْتَبُ الْمُدَرِّسِ. مَكَاتِبُ الطُّلَّابِ. أَبْوَابُهَا. فَصْلُنَا. لُغَاتُهُمْ.</span><span class="rule-example-ru">11. <span dir="rtl" lang="ar">مُضَافٌ وَمُضَافٌ إِلَيْهِ</span> — первый и второй члены идафы.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">هَذِهِ مَدْرَسَتِي. هِيَ قَرِيبَةٌ. أَبْوَابُهَا مَفْتُوحَةٌ. ذَاكَ كُرْسِيُّهُ. مَكْتَبُ الْمُدَرِّسِ كَبِيرٌ. هَذَا مُدَرِّسُنَا.</span><span class="rule-example-ru">12. <span dir="rtl" lang="ar">مُبْتَدَأٌ وَخَبَرٌ</span> — мубтада и хабар.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">فِيهِ نَافِذَتَانِ كَبِيرَتَانِ. الطَّالِبَانِ مُجْتَهِدَانِ.</span><span class="rule-example-ru">13. <span dir="rtl" lang="ar">الْمُثَنَّى</span> — двойственное число.</span></div><div class="rule-example-card rule-term-number"><span class="rule-example-ar" dir="rtl" lang="ar">ثَلَاثَةُ أَبْوَابٍ. عَشَرَةُ طُلَّابٍ.</span><span class="rule-example-ru">14. <span dir="rtl" lang="ar">الْعَدَدُ</span> — числительное и считаемое слово.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">فِي الْمَدْرَسَةِ فُصُولٌ. فِي فَصْلِنَا عَشَرَةُ طُلَّابٍ. هُمْ مِنْ بِلَادٍ مُخْتَلِفَةٍ.</span><span class="rule-example-ru">15. <span dir="rtl" lang="ar">حُرُوفُ الْجَرِّ</span> — предлоги и управляемые ими имена.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Цветной разбор автора</span><table><thead><tr><th>Предложение</th><th>Синтаксическая структура</th></tr></thead><tbody><tr><td><span dir="rtl" lang="ar">أَبْوَابُهَا</span></td><td><span dir="rtl" lang="ar">أَبْوَابُ — مُضَافٌ؛ ـهَا — مُضَافٌ إِلَيْهِ</span></td></tr><tr><td><span dir="rtl" lang="ar">فَصْلُنَا</span></td><td><span dir="rtl" lang="ar">فَصْلُ — مُضَافٌ؛ ـنَا — مُضَافٌ إِلَيْهِ</span></td></tr><tr><td><span dir="rtl" lang="ar">هَذِهِ مَدْرَسَتِي</span></td><td><span dir="rtl" lang="ar">هَذِهِ — مُبْتَدَأٌ؛ مَدْرَسَتِي — خَبَرٌ، وَهِيَ مُضَافٌ وَالْيَاءُ مُضَافٌ إِلَيْهِ</span></td></tr><tr><td><span dir="rtl" lang="ar">ذَاكَ كُرْسِيُّهُ</span></td><td><span dir="rtl" lang="ar">ذَاكَ — مُبْتَدَأٌ؛ كُرْسِيُّهُ — خَبَرٌ، وَهُوَ مُضَافٌ وَالْهَاءُ مُضَافٌ إِلَيْهِ</span></td></tr><tr><td><span dir="rtl" lang="ar">مَكْتَبُ الْمُدَرِّسِ كَبِيرٌ</span></td><td><span dir="rtl" lang="ar">مَكْتَبُ — مُبْتَدَأٌ وَمُضَافٌ؛ الْمُدَرِّسِ — مُضَافٌ إِلَيْهِ؛ كَبِيرٌ — خَبَرٌ</span></td></tr><tr><td><span dir="rtl" lang="ar">لُغَاتُهُمْ مُخْتَلِفَةٌ</span></td><td><span dir="rtl" lang="ar">لُغَاتُهُمْ — مُبْتَدَأٌ، وَهُوَ مُضَافٌ وَهُمْ مُضَافٌ إِلَيْهِ؛ مُخْتَلِفَةٌ — خَبَرٌ</span></td></tr><tr><td><span dir="rtl" lang="ar">هِيَ مَدْرَسَةٌ كَبِيرَةٌ</span></td><td><span dir="rtl" lang="ar">هِيَ — مُبْتَدَأٌ؛ مَدْرَسَةٌ — خَبَرٌ؛ كَبِيرَةٌ — نَعْتٌ</span></td></tr></tbody></table></div></div>$$
  where id = review_rule_id;

  insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order) values
    (review_rule_id, 'Sharkh_na_1_tom_Med_kursa.pdf', $$الدَّرْسُ الْحَادِي وَالْعِشْرُونَ
هَذَا الدَّرْسُ مُرَاجَعَةٌ لِبَعْضِ الدُّرُوسِ السَّابِقَةِ .
١- أَسْمَاءُ الْإِشَارَةِ لِلْقَرِيبِ الْمُذَكَّرِ : هَذَا فَصْلُنَا . هَذَا مَكْتَبُ الْمُدَرِّسِ . هَذَا مُحَمَّدٌ . هَذَا مُدَرِّسُنَا .
٢- أَسْمَاءُ الْإِشَارَةِ لِلْقَرِيبِ الْمُؤَنَّثِ : هَذِهِ مَدْرَسَتِي . هَذِهِ مَكْتَبَةُ الْمَدْرَسَةِ . هَذِهِ مَرْيَمُ . هَذِهِ مُدَرِّسَتُنَا .
٣- أَسْمَاءُ الْإِشَارَةِ لِلْبَعِيدِ الْمُذَكَّرِ : ذَاكَ كُرْسِيُّهُ . ذَلِكَ مَكْتَبُ الْمُدَرِّسِ . ذَاكَ مُحَمَّدٌ، وَذَلِكَ عَلِيٌّ .
٤- أَسْمَاءُ الْإِشَارَةِ لِلْبَعِيدِ الْمُؤَنَّثِ : تِلْكَ مَكَاتِبُ الطُّلَّابِ . تِلْكَ فَاطِمَةُ . تِلْكَ الْكُتُبُ لِلْمُدَرِّسِينَ .
٥- يَاءُ الْمُتَكَلِّمِ : هَذِهِ مَدْرَسَتِي . تِلْكَ حَقِيبَتِي . هَؤُلَاءِ أَصْدِقَائِي .
٦- ضَمِيرُ الْجَمْعِ لِلْمُتَكَلِّمِ : هَذَا فَصْلُنَا . فِي فَصْلِنَا عَشَرَةُ طُلَّابٍ . هَذَا مُدَرِّسُنَا، نَحْنُ نُحِبُّهُ .
٧- ضَمِيرُ الْغَائِبِ لِلْمُفْرَدِ الْمُذَكَّرِ : هُوَ فَصْلٌ وَاسِعٌ . فِيهِ نَافِذَتَانِ . فِيهِ مَكَاتِبُ . فِيهِ سَبُّورَةٌ . هُوَ مِنَ الْيَابَانِ .
٨- ضَمِيرُ الْغَائِبِ لِلْمُفْرَدِ الْمُؤَنَّثِ : هِيَ قَرِيبَةٌ . هِيَ مَدْرَسَةٌ كَبِيرَةٌ . لَهَا ثَلَاثَةُ أَبْوَابٍ . أَبْوَابُهَا مَفْتُوحَةٌ .$$, 33, 33, 1),
    (review_rule_id, 'Sharkh_na_1_tom_Med_kursa.pdf', $$٩- ضَمِيرُ الْغَائِبِ لِلْجَمْعِ الْمُذَكَّرِ : كَرَاسِيُّهُمْ . هُمْ مِنْ بِلَادٍ مُخْتَلِفَةٍ . لُغَاتُهُمْ مُخْتَلِفَةٌ . أَلْوَانُهُمْ مُخْتَلِفَةٌ . دِينُهُمْ وَاحِدٌ .
١٠- مَنْعُوتٌ وَنَعْتٌ : مَدْرَسَةٌ كَبِيرَةٌ . فُصُولٌ كَبِيرَةٌ . فَصْلٌ وَاسِعٌ . نَافِذَتَانِ كَبِيرَتَانِ . هُمْ مِنْ بِلَادٍ مُخْتَلِفَةٍ . رَجُلٌ صَالِحٌ .
١١- مُضَافٌ وَمُضَافٌ إِلَيْهِ : ثَلَاثَةُ أَبْوَابٍ . مَكْتَبُ الْمُدَرِّسِ . مَكَاتِبُ الطُّلَّابِ . أَبْوَابُهَا . فَصْلُنَا . لُغَاتُهُمْ .
١٢- مُبْتَدَأٌ وَخَبَرٌ : هَذِهِ مَدْرَسَتِي . هِيَ قَرِيبَةٌ . أَبْوَابُهَا مَفْتُوحَةٌ . ذَاكَ كُرْسِيُّهُ . مَكْتَبُ الْمُدَرِّسِ كَبِيرٌ . هَذَا مُدَرِّسُنَا .
١٣- الْمُثَنَّى : فِيهِ نَافِذَتَانِ كَبِيرَتَانِ . الطَّالِبَانِ مُجْتَهِدَانِ .
١٤- الْعَدَدُ : ثَلَاثَةُ أَبْوَابٍ . عَشَرَةُ طُلَّابٍ .
١٥- حُرُوفُ الْجَرِّ : فِي الْمَدْرَسَةِ فُصُولٌ . فِي فَصْلِنَا عَشَرَةُ طُلَّابٍ . هُمْ مِنْ بِلَادٍ مُخْتَلِفَةٍ .$$, 34, 34, 2),
    (review_rule_id, 'Sharkh_na_1_tom_Med_kursa.pdf', $$أَبْوَابُهَا : أَبْوَابُ مُضَافٌ، ـهَا مُضَافٌ إِلَيْهِ . فَصْلُنَا : فَصْلُ مُضَافٌ، ـنَا مُضَافٌ إِلَيْهِ .
هَذِهِ مَدْرَسَتِي : هَذِهِ مُبْتَدَأٌ، مَدْرَسَتِي خَبَرٌ، وَهِيَ مُضَافٌ، وَالْيَاءُ مُضَافٌ إِلَيْهِ .
